#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import json
import sys
import zipfile
from pathlib import Path

from lxml import etree

TEMPLATE_PATH = Path('/root/safety_audit_template.hwpx')
OVERVIEW_PATH = Path('/root/audit_overview.json')
ACTIONS_PATH = Path('/root/corrective_actions.json')
OUTPUT_PATH = Path('/root/safety_audit_brief_final.hwpx')


def load_json(path: Path):
    with path.open('r', encoding='utf-8') as f:
        return json.load(f)


def convert_date_yyyy_mm_dd_to_dots(s: str) -> str:
    # Expected: YYYY-MM-DD
    parts = s.split('-')
    if len(parts) != 3 or any(len(p) != 2 for p in parts[1:]) or len(parts[0]) != 4:
        raise ValueError(f'Unexpected date format (expected YYYY-MM-DD): {s!r}')
    return f"{parts[0]}.{parts[1]}.{parts[2]}"


def severity_note_for_risk_tier(tier: str) -> str:
    mapping = {
        'High': '즉시조치',
        'Medium': '계획보완',
        'Low': '모니터링',
    }
    if tier not in mapping:
        raise ValueError(f'Unexpected 위험등급 (expected one of {sorted(mapping)}): {tier!r}')
    return mapping[tier]


def build_substitutions(overview: dict, actions: dict) -> dict:
    if 'summary' not in overview or not isinstance(overview['summary'], dict):
        raise ValueError('audit_overview.json must contain key "summary" as an object')

    summary = overview['summary']

    required_overview_keys = [
        '점검ID',
        '현장명',
        '주관점검자',
        '점검일',
        '위험등급',
        '총평',
        '보고대상',
    ]
    for k in required_overview_keys:
        if k not in summary:
            raise ValueError(f'audit_overview.json summary missing key: {k}')

    if 'immediate_actions' not in actions or not isinstance(actions['immediate_actions'], list):
        raise ValueError('corrective_actions.json must contain key "immediate_actions" as a list')

    immediate_actions = actions['immediate_actions']
    if len(immediate_actions) < 3:
        raise ValueError('corrective_actions.json immediate_actions must have at least 3 items')

    inspection_date = convert_date_yyyy_mm_dd_to_dots(str(summary['점검일']))

    risk_tier = str(summary['위험등급'])
    risk_tier_with_note = f"{risk_tier} {severity_note_for_risk_tier(risk_tier)}"

    subs = {
        '{{점검ID}}': str(summary['점검ID']),
        '{{현장명}}': str(summary['현장명']),
        '{{주관점검자}}': str(summary['주관점검자']),
        '{{점검일}}': inspection_date,
        '{{위험등급}}': risk_tier_with_note,
        '{{총평}}': str(summary['총평']),
        '{{보고대상}}': str(summary['보고대상']),
        '{{조치1}}': str(immediate_actions[0]),
        '{{조치2}}': str(immediate_actions[1]),
        '{{조치3}}': str(immediate_actions[2]),
    }

    return subs


def replace_placeholders_in_xml(xml_text: str, subs: dict, entry_name: str) -> str:
    for placeholder, value in subs.items():
        xml_text = xml_text.replace(placeholder, value)

    if '{{' in xml_text:
        idx = xml_text.index('{{')
        context = xml_text[max(0, idx - 120): idx + 120]
        raise RuntimeError(
            f'LEFTOVER PLACEHOLDER in {entry_name}: ...{context}...'
        )

    return xml_text


def clear_linesegarray_layout_cache(xml_bytes: bytes) -> bytes:
    # Remove stale layout caches to avoid overlapping characters.
    tree = etree.fromstring(xml_bytes)

    # Some templates use lineSegArray; others use linesegarray.
    elems = tree.xpath(
        '//*[translate(local-name(), "ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz")="linesegarray"]'
    )
    for elem in elems:
        parent = elem.getparent()
        if parent is not None:
            parent.remove(elem)

    return etree.tostring(tree, xml_declaration=True, encoding='UTF-8')


def main() -> int:
    overview = load_json(OVERVIEW_PATH)
    actions = load_json(ACTIONS_PATH)
    subs = build_substitutions(overview, actions)

    with zipfile.ZipFile(TEMPLATE_PATH, 'r') as zin:
        names = zin.namelist()
        original_entries = {n: zin.read(n) for n in names}

    rebuilt_entries = {}
    for name in names:
        data = original_entries[name]
        if name.endswith('.xml'):
            xml_text = data.decode('utf-8')
            xml_text = replace_placeholders_in_xml(xml_text, subs, name)
            xml_bytes = xml_text.encode('utf-8')
            xml_bytes = clear_linesegarray_layout_cache(xml_bytes)
            rebuilt_entries[name] = xml_bytes
        else:
            rebuilt_entries[name] = data

    # Final safety check: no placeholders left anywhere in XML files.
    for name in names:
        if name.endswith('.xml'):
            check_text = rebuilt_entries[name].decode('utf-8', errors='replace')
            if '{{' in check_text:
                idx = check_text.index('{{')
                print('LEFTOVER PLACEHOLDER in', name)
                print(check_text[max(0, idx - 80): idx + 80])
                return 2

    # Rebuild the ZIP.
    # If a 'mimetype' entry exists, write it first with ZIP_STORED.
    OUTPUT_PATH.unlink(missing_ok=True)
    with zipfile.ZipFile(OUTPUT_PATH, 'w') as zout:
        if 'mimetype' in names:
            zout.writestr('mimetype', rebuilt_entries['mimetype'], compress_type=zipfile.ZIP_STORED)
        for name in names:
            if name == 'mimetype':
                continue
            zout.writestr(name, rebuilt_entries[name], compress_type=zipfile.ZIP_DEFLATED)

    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except Exception as e:
        print(str(e), file=sys.stderr)
        raise

